from __future__ import annotations

import argparse
import re
import typing
from collections.abc import Iterable
from pathlib import Path

DEFAULT_OUTPUT = (
    Path(__file__).resolve().parents[1]
    / "vocalbin"
    / "deepgram"
    / "generated"
    / "voices.py"
)

# Aura 1 predates the `aura-2-<name>-<language>` naming and is superseded by it.
VOICE_PATTERN = re.compile(r"^aura-2-[a-z0-9]+-[a-z]{2}$")


def identifier(voice_id: str) -> str:
    return voice_id.replace("-", "_").upper()


def render(voice_ids: Iterable[str]) -> str:
    lines = [
        "# This file is generated by scripts/generate_deepgram_voices.py.",
        "# Do not edit it manually.",
        "# Run the generator to refresh the Deepgram Aura voice mapping.",
        "from enum import StrEnum",
        "",
        "",
        "class AuraVoice(StrEnum):",
    ]
    members = [(identifier(voice_id), voice_id) for voice_id in voice_ids]
    if not members:
        lines.append("    pass")
    else:
        lines.extend(f'    {name} = "{voice_id}"' for name, voice_id in members)
    return "\n".join(lines) + "\n"


def fetch_voices() -> list[str]:
    try:
        from deepgram import SpeakV1Model
    except ImportError as exc:
        raise RuntimeError(
            "Voice generation requires the 'deepgram' extra: "
            "uv run --extra deepgram python scripts/generate_deepgram_voices.py"
        ) from exc

    literal, *_ = typing.get_args(SpeakV1Model)
    return sorted(
        voice_id
        for voice_id in typing.get_args(literal)
        if VOICE_PATTERN.match(voice_id)
    )


def write_voices(voice_ids: Iterable[str], output: Path) -> bool:
    content = render(voice_ids)
    if output.exists() and output.read_text(encoding="utf-8") == content:
        return False
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(content, encoding="utf-8", newline="\n")
    return True


def main() -> None:
    parser = argparse.ArgumentParser(
        description="Generate named Deepgram Aura voice constants."
    )
    parser.add_argument("--output", type=Path, default=DEFAULT_OUTPUT)
    args = parser.parse_args()
    voices = fetch_voices()
    changed = write_voices(voices, args.output)
    action = "Updated" if changed else "Already up to date"
    print(f"{action}: {args.output} ({len(voices)} voices)")


if __name__ == "__main__":
    main()
